 const query=useQuery<{items:Exco[];canManage:boolean}>({queryKey:['excos',id],queryFn:async()=>(await api.get(`/communities/${id}/excos`)).data});
 useEffect(()=>{if(addExco==='1'){setAddOpen(true);router.setParams({addExco:undefined})}},[addExco]);
