 const closeAction=()=>{setAction(null);setPendingAction(null);setConfirmationName('')};
 const update=useMutation({mutationFn:(v:{item:Exco;status:'ACTIVE'|'INACTIVE';confirmationName:string})=>api.patch(`/communities/${id}/excos/${v.item.Id}`,{status:v.status,confirmationName:v.confirmationName}),onSuccess:()=>{qc.invalidateQueries({queryKey:['excos',id]});closeAction()},onError:(e:any)=>Alert.alert('Update failed',e.response?.data?.error||e.response?.data?.message||'Please try again.')});
 const remove=useMutation({mutationFn:(v:{item:Exco;confirmationName:string})=>api.delete(`/communities/${id}/excos/${v.item.Id}`,{data:{confirmationName:v.confirmationName}}),onSuccess:()=>{qc.invalidateQueries({queryKey:['excos',id]});closeAction()},onError:(e:any)=>Alert.alert('Remove failed',e.response?.data?.error||e.response?.data?.message||'Please try again.')});
 const items=query.data?.items||[];const visible=useMemo(()=>items.filter(x=>x.Status==='ACTIVE'&&`${x.FirstName} ${x.LastName} ${x.Email} ${x.Position} ${x.Department||''}`.toLowerCase().includes(search.trim().toLowerCase())),[items,search]);
 const active=items.filter(x=>x.Status==='ACTIVE');const roles=new Set(active.map(x=>x.Position)).size;const years=active.map(x=>new Date(x.AppointedDate).getFullYear()).filter(Boolean);const firstYear=years.length?Math.min(...years):0;const lastYear=years.length?Math.max(new Date().getFullYear(),...years):0;const tenure=years.length?(firstYear===lastYear?String(firstYear):`${firstYear}–${lastYear}`):'Not set';
 function closeAdd(){setAddOpen(false);setSelected(null);setPosition('');setCustomPost(false);setDepartment('');setAppointed(today());setTenureEnd('');setNotes('');setPicker(null)}
